namespace HakutaiKagami.Core.Contracts;

public enum BattlefieldAction { Equip, ReturnGear, Load, Unload, Rest }
public sealed record BattlefieldInput(EntityId Id,BattlefieldAction Action,EntityId Unit,TroopKind Kind=TroopKind.Spear,string Good="spear",int Amount=0);
public sealed record BattlefieldOrder(BattlefieldInput Input,EntityId Actor,EntityId Owner,EntityId Army,EntityId Site,long At,long Revision);
public sealed record BattlefieldState(int Schema,string Policy,BattlefieldOrder[] Orders){[System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] public TempleMilitaryOrder[]? Temples{get;init;}}
public static partial class BattlefieldRules
{
 internal static BattlefieldOrder[] Orders(ContractWorld w)=>w.Battlefield?.Orders??[];
 static bool Before(BattlefieldOrder o,long at,long rev)=>o.At<at||o.At==at&&o.Revision<rev;
 static void Need(bool ok,string why){if(!ok)throw new InvalidDataException(why);}
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>Orders(w).Any(o=>o.Input.Id==id)||TempleMilitary.Orders(w).Any(o=>o.Input.Id==id);
 public static string Gear(TroopKind kind)=>kind switch{TroopKind.Spear=>"spear",TroopKind.Bow=>"bow",TroopKind.Gun=>"gun",TroopKind.Cavalry=>"horse",TroopKind.Transport=>"cart",_=>throw new InvalidDataException("未知の兵種です")};
 public static string[] Goods=>["spear","bow","gun","horse","cart","arrow","powder","bullet","fodder"];
 public static bool Crafted(string good)=>good is "gun" or "powder" or "bullet";
 // 新しい開始方針の試作配備。各拠点の家の所有として一度だけ定義する。
 public static int Initial(string good)=>good switch{"spear"=>100,"bow"=>30,"horse"=>10,"cart"=>10,"arrow"=>300,"fodder"=>100,_=>0};
 public static BattlefieldLoadout Loadout(ContractWorld w,EntityId unit,long at=long.MaxValue,long rev=long.MaxValue){using var _ccRev=ControlContext.At(rev);if(unit==TempleMilitary.Unit&&BattlefieldRules.Enabled(w))return new(unit,TroopKind.Spear,20);var o=Orders(w).LastOrDefault(o=>o.Input.Unit==unit&&o.Input.Action is BattlefieldAction.Equip or BattlefieldAction.ReturnGear&&Before(o,at,rev));return o?.Input.Action==BattlefieldAction.Equip?new(unit,o.Input.Kind,o.Input.Amount):new(unit,TroopKind.Spear,0);}
 static long Movement(BattlefieldOrder o,string good)=>o.Input.Good!=good?0:o.Input.Action is BattlefieldAction.Equip or BattlefieldAction.Load?o.Input.Amount:o.Input.Action is BattlefieldAction.ReturnGear or BattlefieldAction.Unload?-o.Input.Amount:0;
 internal static long CraftReserved(ContractWorld w,EntityId owner,EntityId site,string good,long at,long rev)=>Crafted(good)?Orders(w).Where(o=>o.Owner==owner&&o.Site==site&&Before(o,at,rev)).Sum(o=>Movement(o,good)):0;
 public static long Depot(ContractWorld w,EntityId owner,EntityId site,string good,long at=long.MaxValue,long rev=long.MaxValue){using var _ccRev=ControlContext.At(rev);Need(Goods.Contains(good),"未定義の軍需品です");if(!Enabled(w))return 0;if(Crafted(good))return CraftTrade.Stock(w,owner,site,good,at,rev);return (RegionalDomains.Owner(w,site)==owner?Initial(good):0)-Orders(w).Where(o=>o.Owner==owner&&o.Site==site&&Before(o,at,rev)).Sum(o=>Movement(o,good));}
 public static long Carried(ContractWorld w,EntityId unit,string good,long at=long.MaxValue,long rev=long.MaxValue)=>Orders(w).Where(o=>o.Input.Unit==unit&&Before(o,at,rev)).Sum(o=>o.Input.Good==good?o.Input.Action==BattlefieldAction.Load?o.Input.Amount:o.Input.Action==BattlefieldAction.Unload?-o.Input.Amount:0:0)-Spent(w,unit,good,at,rev)-(good=="fodder"?ExpeditionFodder.Spent(w,unit,at,rev):0);
 static long Spent(ContractWorld w,EntityId unit,string good,long at,long rev)=>(w.WorldClashes?.Steps??[]).Where(s=>s.At<at||s.At==at&&s.Revision<rev).SelectMany(s=>s.Result.Expenses??[]).Where(e=>e.Unit==unit&&e.Good==good).Sum(e=>e.Amount);
 internal static void Rewind(ContractWorld w,long at,long rev){using var _ccRev=ControlContext.At(rev);if(w.Battlefield!=null)w.Battlefield=w.Battlefield with{Orders=Orders(w).Where(o=>o.At<at||o.At==at&&o.Revision<=rev).ToArray(),Temples=w.Battlefield.Temples==null?null:TempleMilitary.Orders(w).Where(o=>o.At<at||o.At==at&&o.Revision<=rev).ToArray()};}
 static void Check(ContractWorld w,BattlefieldOrder o){var i=o.Input;Need(Enabled(w)&&EntityId.IsValid(i.Id.Value)&&Enum.IsDefined(i.Action)&&Enum.IsDefined(i.Kind)&&Goods.Contains(i.Good)&&i.Amount>0,"軍需品の入力が不正です");var ledger=NewGameMilitary.LedgerStates(w).SingleOrDefault(l=>l.Terms.Army==o.Army);Need(ledger!=null&&ledger.Terms.Owner==o.Owner,"所有する軍の原本がありません");var context=NewGameMilitary.WorldEngagementBefore(w,o.Army,o.At,o.Revision-1);Need(NewGameMilitary.CustodyAt(context,o.At,o.Revision)&&!NewGameMilitary.Deployed(context)&&TransportWork.At(w,o.Actor,o.Site,o.At,o.Revision,true)&&o.Actor==ControlSuccession.PlayerAtRevision(w,o.Revision)&&o.Site==ledger!.Terms.Site&&NewGameMilitary.UnitIdsFor(context).Contains(i.Unit),"兵を引き受けた本人が本拠で受け渡してください");var loadout=Loadout(w,i.Unit,o.At,o.Revision);if(i.Action==BattlefieldAction.Equip){Need(loadout.Equipped==0&&i.Good==Gear(i.Kind)&&i.Amount<=context.Units.Single(u=>u.Id==i.Unit).Soldiers&&Depot(w,o.Owner,o.Site,i.Good,o.At,o.Revision)>=i.Amount,"装備・兵数の上限を超えるか、返却前です");}else if(i.Action==BattlefieldAction.ReturnGear){Need(loadout.Equipped==i.Amount&&loadout.Kind==i.Kind&&i.Good==Gear(loadout.Kind),"引受済みの装備一式だけを返却できます");}else if(i.Action==BattlefieldAction.Load){Need(i.Good is "arrow" or "powder" or "bullet" or "fodder"&&i.Amount<=1000&&Depot(w,o.Owner,o.Site,i.Good,o.At,o.Revision)>=i.Amount&&Carried(w,i.Unit,i.Good,o.At,o.Revision)+i.Amount<=1000,"軍需品の在庫・携行上限を確認してください");}else if(i.Action==BattlefieldAction.Unload){Need(i.Good is "arrow" or "powder" or "bullet" or "fodder"&&Carried(w,i.Unit,i.Good,o.At,o.Revision)>=i.Amount,"実際に携行している軍需品だけを返却できます");}else if(i.Action==BattlefieldAction.Rest){int pending=Orders(w).Where(q=>q.Input.Unit==i.Unit&&q.Input.Action==BattlefieldAction.Rest&&Before(q,o.At,o.Revision)&&q.At+5*86400>o.At).Sum(q=>q.Input.Amount);Need(CommunityEconomy.Enabled(w)&&CommunityEconomy.SitesFor(w).Contains(o.Site)&&i.Good=="spear"&&i.Kind==TroopKind.Spear&&i.Amount<=Casualties(w,i.Unit,o.At,o.Revision).Wounded-pending&&CommunityEconomy.AccountAt(w,o.Site,o.At,o.Revision).HouseRice-HouseSalary.Reserved(w,o.Site,o.At,o.Revision)>=3L*i.Amount,"未療養の負傷兵と5日分の米が必要です");}else throw new InvalidDataException("未対応の軍需処理です");}
 internal static void Apply(ContractWorld w,BattlefieldInput i){var t=w.NewMilitary?.Terms??throw new InvalidDataException("先に軍務で兵を引き受けてください");var o=new BattlefieldOrder(i,w.PlayerControl,t.Owner,t.Army,t.Site,w.ElapsedSeconds,w.CommitSequence);Check(w,o);w.Battlefield??=new(1,Policy,[]);w.Battlefield=w.Battlefield with{Orders=[..Orders(w),o]};}
 public static void Validate(ContractWorld w,ContractWorld? prior){TempleMilitary.Validate(w,prior);if(w.Battlefield==null){Need(prior?.Battlefield==null,"装備の原本を消せません");return;}Need(Enabled(w)&&w.Battlefield.Schema==1&&w.Battlefield.Policy==Policy,"軍需品の保存形式が不正です");if(prior?.Battlefield!=null)Need(Orders(w).Take(prior.Battlefield.Orders.Length).SequenceEqual(prior.Battlefield.Orders),"過去の装備受渡しを変更できません");Need(Orders(w).Select(o=>o.Input.Id).Concat(TempleMilitary.Orders(w).Select(o=>o.Input.Id)).Distinct().Count()==Orders(w).Length+TempleMilitary.Orders(w).Length,"装備と寺社で原本IDを重複できません");var ids=new HashSet<EntityId>();long at=0,rev=0;foreach(var o in Orders(w)){Need(ids.Add(o.Input.Id)&&o.At>=at&&o.At<=w.ElapsedSeconds&&o.Revision>rev&&o.Revision<=w.CommitSequence,"装備の順序・重複が不正です");Check(w,o);at=o.At;rev=o.Revision;}}
}
public sealed partial class WorldSession
{
 public CommandResult ManageBattlefield(BattlefieldInput i,long revision){using var _ccRev=ControlContext.At(revision);lock(gate){var old=BattlefieldRules.Orders(state).SingleOrDefault(o=>o.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");if(NewGameWork.OwnIdUsed(state,i.Id)||state.Requests.Any(r=>r.Id==i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"使用済みの原本です");try{Change(w=>BattlefieldRules.Apply(w,i));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"現地の軍需品を受け渡しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
